"""UMAP of ground-truth cells vs cells generated by our decoder and by baselines (runs on the VM; reads runs/<tag>/gen_<split>.npz).

python figures/umap_compare.py --task cond --name pbmc --split val --tags "CAD=c_cond_freq" "Cell-type mean=cb_type_mean" --out ~/cad_out/figs/umap_cond_val
PCA and UMAP are fit on REAL cells only (train subsample + held-out real cells); generated cells are projected with the same
log-CP10k -> PCA -> UMAP transform. Writes <out>.pdf/.png and <out>.json (metrics echo).
"""
import argparse
import json
import os
import sys
import numpy as np
import scipy.sparse as sp
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
from matplotlib import font_manager
_F = os.path.join(os.path.dirname(__file__), "..", "fonts", "GoogleSans-Regular.ttf")
if os.path.exists(_F):   # same face as the schematic figures
    font_manager.fontManager.addfont(_F)
    plt.rcParams["font.family"] = font_manager.FontProperties(fname=_F).get_name()

sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))
from src.cell_eval import World  # noqa: E402
from src.evaluate import log_cp10k  # noqa: E402

PAL = ["#4F7FB8", "#D9713F", "#23918F", "#6F5FB0", "#C9A227", "#B04F7F", "#5C8A3A", "#8C5A3C"]


READABLE = {"B cell": "B cell", "CD14-low, CD16-positive monocyte": "CD14-low CD16+ monocyte",
            "CD14-positive monocyte": "CD14+ monocyte", "CD16-negative, CD56-bright natural killer cell, human": "CD16- CD56-bright NK cell",
            "CD4-positive, alpha-beta cytotoxic T cell": "CD4+ cytotoxic T cell",
            "central memory CD4-positive, alpha-beta T cell": "central memory CD4+ T cell",
            "central memory CD8-positive, alpha-beta T cell": "central memory CD8+ T cell",
            "effector memory CD4-positive, alpha-beta T cell": "effector memory CD4+ T cell",
            "effector memory CD8-positive, alpha-beta T cell": "effector memory CD8+ T cell",
            "naive thymus-derived CD4-positive, alpha-beta T cell": "naive CD4+ T cell",
            "naive thymus-derived CD8-positive, alpha-beta T cell": "naive CD8+ T cell", "natural killer cell": "NK cell"}


def short(u, n=30):
    if u in READABLE:
        return READABLE[u]
    for a, b in (("-positive", "+"), ("-negative", "-"), ("natural killer cell", "NK cell"), ("alpha-beta ", "")):
        u = u.replace(a, b)
    u = u.strip(" ,")
    return u if len(u) <= n else u[: n - 1].rstrip(" ,") + "..."


def load_gen(path, G):
    z = np.load(path, allow_pickle=True)
    out = {}
    for u in z["units"]:
        ptr = z[f"{u}__ptr"]
        out[str(u)] = sp.csr_matrix((z[f"{u}__data"], z[f"{u}__ind"], ptr), shape=(len(ptr) - 1, G)).toarray()
    return out


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--task", required=True)
    ap.add_argument("--name", required=True)
    ap.add_argument("--split", default="val")
    ap.add_argument("--tags", nargs="+", required=True, help='"Label=tag"')
    ap.add_argument("--out", required=True)
    ap.add_argument("--n-real", type=int, default=150)
    ap.add_argument("--n-colors", type=int, default=6)
    ap.add_argument("--width", type=float, default=6.5, help="figure width in inches = printed width, so fonts print at their size")
    ap.add_argument("--height", type=float, default=2.5)
    a = ap.parse_args()
    import umap
    w = World(a.task, a.name)
    G = len(w.panel)
    tags = dict(t.split("=", 1) for t in a.tags)
    gens = {lab: load_gen(os.path.join(w.dir, "runs", t, f"gen_{a.split}.npz"), G) for lab, t in tags.items()}
    units = sorted(set.intersection(*[set(g) for g in gens.values()]))
    rng = np.random.default_rng(0)
    real = {}
    for u in units:
        idx = np.where((w.lab == u) & (w.split == a.split) & ~w.ctrl)[0]
        real[u] = w.counts(rng.choice(idx, min(len(idx), a.n_real), replace=False))
    tr = np.where((w.split == "train") & ~w.ctrl)[0]
    bg = w.counts(np.sort(rng.choice(tr, min(len(tr), 6000), replace=False)))
    emb = lambda C: w.pca.transform(log_cp10k(C))
    fit = np.vstack([emb(bg)] + [emb(real[u]) for u in units])
    um = umap.UMAP(n_neighbors=30, min_dist=0.3, random_state=0).fit(fit)
    size = {u: len(real[u]) for u in units}
    show = sorted(units, key=lambda u: -size[u])[: a.n_colors]
    col = {u: PAL[i % len(PAL)] for i, u in enumerate(show)}
    panels = [("Held-out real", {u: real[u] for u in units})] + [(lab, gens[lab]) for lab in tags]
    xy = {name: {u: um.transform(emb(C)) for u, C in d.items()} for name, d in panels}
    allp = np.vstack([v for d in xy.values() for v in d.values()])
    lo, hi = allp.min(0) - .5, allp.max(0) + .5
    fig, axs = plt.subplots(1, len(panels), figsize=(a.width, a.height), sharex=True, sharey=True)
    for ax, (name, _) in zip(np.atleast_1d(axs), panels):
        bgp = um.transform(emb(bg[:2000]))
        ax.scatter(bgp[:, 0], bgp[:, 1], s=.6, c="#D9DCE1", lw=0, rasterized=True)
        for u in units:
            if u in col:
                continue
            ax.scatter(*xy[name][u].T, s=1.2, c="#9AA3AF", lw=0, alpha=.5, rasterized=True)
        for u in show:
            ax.scatter(*xy[name][u].T, s=2.4, c=col[u], lw=0, alpha=.8, rasterized=True, label=short(u))
        ax.set_title(name, fontsize=7, pad=2)
        ax.set_xlim(lo[0], hi[0]); ax.set_ylim(lo[1], hi[1]); ax.set_xticks([]); ax.set_yticks([])
        for s in ax.spines.values():
            s.set_visible(False)
    h, l = np.atleast_1d(axs)[0].get_legend_handles_labels()
    fig.legend(h, l, loc="lower center", ncol=min(len(l), 3), fontsize=6.5, frameon=False, markerscale=2.5, handletextpad=.2, columnspacing=1.2)
    fig.tight_layout(rect=(0, .12, 1, 1))
    os.makedirs(os.path.dirname(a.out) or ".", exist_ok=True)
    fig.savefig(a.out + ".pdf", dpi=300); fig.savefig(a.out + ".png", dpi=200)
    json.dump({"units": units, "colored": show, "tags": tags, "split": a.split}, open(a.out + ".json", "w"), indent=1)
    print("wrote", a.out)


if __name__ == "__main__":
    main()
